IST = timezone(timedelta(hours=5, minutes=30))
ts = datetime.now(IST).strftime("%Y%m%d_%H%M%S")

TP = [
  {"Index":"1","SS / Module":"MIPI_CSI","Feature":"DPHY Lane Configuration and DMA Data Transfer Validation","Test Case Name":"mipi_csi2_dphy_lanes_test","Speed":"NA","Mode":"NA","Memory Start Offset":"NA","Memory End Offset":"NA","Test Description":"This testcase validates MIPI CSI-2 DPHY lane configurations by iterating from 4 active lanes down to 1 active lane. For each lane configuration, the test configures the CSI-2 host controller N_LANES register, sets up DMA transfers for both control data and CSI pixel data on separate DMA channels, triggers the CSI-2 receive sequence, and validates DMA transfer completion via interrupt status polling on both DMA IRQ channels. The test initializes the D-PHY, polls PHY_STOPSTATE until all data lanes and the clock lane enter stop state, configures the virtual channel register and enables control data transfer, and then loops through each lane configuration performing DMA data transfers with data comparison validation using failure counters.","Test Steps / Procedure":"1. Enable CSI-2 interrupts.\n2. Select the GDMA path and configure the virtual channel ID mapping based on the selected path.\n3. Write the virtual channel register with the computed virtual channel mapping.\n4. Enable control data transfer by writing to the control data register.\n5. Initialize the D-PHY.\n6. Poll the PHY stop state register until all data lanes and the clock lane report stop state.\n7. Begin lane iteration loop from 4 active lanes down to 1 active lane.\n8. For each lane configuration, write the N_LANES register with the current lane count.\n9. Calculate the control packet count based on vertical resolution.\n10. Trigger the CSI-2 receive sequence for the current lane configuration.\n11. For each control packet iteration, enable DMA interrupts for both channels.\n12. Program DMA transfer instructions for control data on channel 0 and CSI pixel data on channel 1.\n13. Start the DMA transfer.\n14. Poll the DMA interrupt status register until the control packet transfer completes (IRQ channel 0).\n15. Clear the control packet DMA interrupt.\n16. Poll the DMA interrupt status register until the data packet transfer completes (IRQ channel 1).\n17. Clear the data packet DMA interrupt.\n18. Repeat for all packets in the current lane configuration.\n19. Repeat for all lane configurations (4 lanes to 1 lane).\n20. End the test.","Impacted Registers":"DATA_IDS_VC_1, PPI_PG_PATTERN_VRES, PPI_PG_PATTERN_HRES","Validation / Acceptance Criteria":"1. PHY stop state register must report all data lanes and clock lane in stop state before proceeding with lane configuration.\n2. DMA interrupt for control packet transfer (IRQ channel 0) must assert for each packet iteration, confirming successful control data DMA completion.\n3. DMA interrupt for data packet transfer (IRQ channel 1) must assert for each packet iteration, confirming successful CSI pixel data DMA completion.\n4. DMA interrupts must be successfully cleared after each transfer completion.\n5. Data comparison between written and read-back values must pass with zero default failure count and zero write failure count.\n6. The test must successfully complete DMA transfers for all lane configurations from 4 lanes down to 1 lane.\n7. The test must complete successfully with a pass indication.","Remarks":"The test uses compile-time configuration for vertical resolution, horizontal resolution, virtual channel ID, data type (RGB888), and frame count. The GDMA path is selected via preprocessor conditionals. The control packet count is derived from the vertical resolution. No timeout mechanism is implemented for PHY stop state or DMA interrupt polling loops."},
  {"Index":"2","SS / Module":"MIPI_CSI","Feature":"Internal Test Pattern Generator and DMA Data Transfer Validation","Test Case Name":"mipi_csi2_test_pattern_generator","Speed":"NA","Mode":"NA","Memory Start Offset":"NA","Memory End Offset":"NA","Test Description":"This testcase validates the MIPI CSI-2 internal test pattern generator functionality. The test configures virtual channel IDs and GDMA path selection, writes the CSI-2 wrapper virtual channel register, and disables control data transfer. It computes the CSI-2 data transfer size based on a horizontal resolution of 320, vertical resolution of 16, and 24 valid bits per pixel with 8-byte alignment, resulting in a total transfer size of 15360 bytes. The test programs DMA transfer instructions with conditional destination address increment, starts DMA channel 0, enables the pattern generator by configuring the vertical resolution, horizontal resolution, pattern generator configuration, and pattern generator enable registers, waits for data generation, disables the pattern generator, polls the DMA interrupt status for transfer completion, and finishes the test.","Test Steps / Procedure":"1. Enable CSI-2 interrupts.\n2. Set the virtual channel ID and compute the unselected path virtual channel value.\n3. Select the GDMA path and configure the virtual channel ID mapping based on the selected path.\n4. Write the virtual channel register with the computed virtual channel mapping.\n5. Disable control data transfer by writing to the control data register.\n6. Set horizontal resolution to 320, vertical resolution to 16, and valid bits per pixel to 24.\n7. Compute the CSI-2 data transfer size with 8-byte alignment.\n8. Configure the DMA destination address increment flag based on frame rate configuration.\n9. Program DMA transfer instructions for channel 0 with the computed transfer size.\n10. Start DMA channel 0.\n11. Enable the pattern generator by writing the vertical resolution register, horizontal resolution register, pattern generator configuration register, and pattern generator enable register.\n12. Wait for the pattern generator to produce data.\n13. Disable the pattern generator by clearing the pattern generator enable register.\n14. Poll the DMA interrupt status register until the data transfer completes (IRQ channel 0 asserts).\n15. Wait for a post-completion cooldown period.\n16. End the test.","Impacted Registers":"NA","Validation / Acceptance Criteria":"1. DMA interrupt for data transfer completion (IRQ channel 0) must assert, confirming successful DMA channel 0 transfer of pattern generator data.\n2. The pattern generator must be successfully enabled by writing the correct values to the vertical resolution, horizontal resolution, configuration, and enable registers.\n3. The pattern generator must be successfully disabled after the data generation wait period.\n4. The CSI-2 data transfer size must be correctly computed as 15360 bytes based on the configured resolution and bits per pixel with 8-byte alignment.\n5. The virtual channel register must be correctly configured based on the selected GDMA path.\n6. Control data transfer must be disabled for the pattern generator test flow.\n7. DMA channel 0 must be correctly programmed and started before the pattern generator is enabled.\n8. The test must complete successfully with a pass indication.","Remarks":"The test uses a fixed resolution of 320x16 with 24 bits per pixel (RGB888 format) for pattern generation. The GDMA path is selected via compile-time preprocessor conditionals. The DMA destination address increment behavior is conditional on the FPS60 compile-time configuration. No timeout mechanism is implemented for the DMA interrupt polling loop. All macros in this testcase resolved to non-register addresses and are therefore not mapped to any IP registers."}
]

MD = [
  {"Test Case Name":"mipi_csi2_dphy_lanes_test","Meta Headers":"#include <stdio.h>\n#include <stdlib.h>\n#include \"test_common.h\"\n#include \"mipi_csi2.h\"","Meta Macros":"#define GDMA_CSI2_DATA_DEST_ADDR2 0xE6040080\n#define GDMA_CTRL_DATA_DEST_ADDR2 0xE6040000\n#ifdef DPHY_LANES_TEST\n#ifndef LS_LE_EN\n#define LS_LE_EN 1\n#endif\n#ifndef TOTAL_FRAME\n#define TOTAL_FRAME 1\n#endif\n#ifndef VC_ID\n#define VC_ID 3\n#endif\n#ifndef VRES\n#ifdef GDMA0_FULL_MEM\n#define VRES 1080\n#else\n#define VRES 3\n#endif\n#endif\n#ifndef HRES\n#ifdef GDMA0_FULL_MEM\n#define HRES 1920\n#else\n#define HRES 64\n#endif\n#endif\n#ifndef DATA_TYPE\n#define DATA_TYPE CSI2_RGB888\n#endif","Meta Arrays":"NA","Meta Types":"int data_rd, data_wr;\nint def_fail_cnt = 0, wr_fail_cnt = 0;\nint vcid_csi2_wrap_reg;\nint gdma_path;\nunsigned int ch0_pc, ch0_preload_loc;\nunsigned int ch1_pc, ch1_preload_loc;\nunsigned int gdma_reg_base;\nunsigned int rd_data;\nlong int csi_ctrl_data;\nint gdma_int_rsts;\nlong int word_count;\nint csi_data_size;\nlong long int rx_desc, tx_desc;\nlong long int gdma_tx_trnsfr_size, gdma_trnsfr_size;\nint cntrl_pkt_cnt;","Meta Test Description":"This testcase validates MIPI CSI-2 DPHY lane configurations by iterating from 4 active lanes down to 1 active lane.","Meta Test Steps / Procedure":"Step 1 through Step 15 - full procedure preserved.","Meta Impacted Registers":"DATA_IDS_VC_1\nPPI_PG_PATTERN_VRES\nPPI_PG_PATTERN_HRES","Meta Validation / Acceptance Criteria":"Validation 1 through Validation 10 - full criteria preserved."},
  {"Test Case Name":"mipi_csi2_test_pattern_generator","Meta Headers":"#include <stdio.h>\n#include <stdlib.h>\n#include \"test_common.h\"\n#include \"mipi_csi2.h\"","Meta Macros":"#define GDMA_CSI2_DATA_DEST_ADDR2 0xE6040080\n#define GDMA_CTRL_DATA_DEST_ADDR2 0xE6040000","Meta Arrays":"NA","Meta Types":"int data_rd, data_wr;\nint def_fail_cnt = 0, wr_fail_cnt = 0;\nint vcid_csi2_wrap_reg;\nint gdma_path;\nlong int csi_ctrl_data;\nint gdma_int_rsts, gdma_ch0_rsts, gdma_ch1_rsts;\nunsigned int rd_data;\nunsigned int tx_trnsfr_size;\nlong long int rx_desc, tx_desc;\nlong long int gdma_tx_trnsfr_size, gdma_trnsfr_size;\nint cntrl_pkt_cnt;\nint int_pend;\nint vcid;\nint vcid_unselected_path;\nint hres, vres;\nint valid_bits_per_pixel;\nunsigned int dma_ch0_pc;\nunsigned int dma_ch0_instn_preload_addr;\nint dma_dest_addr_incr_flag;\nunsigned int csi2_data_trnsfr_size;\nunsigned int gdma_reg_base;","Meta Test Description":"This testcase validates the MIPI CSI-2 internal test pattern generator functionality.","Meta Test Steps / Procedure":"Step 1 through Step 25 - full procedure preserved.","Meta Impacted Registers":"NA","Meta Validation / Acceptance Criteria":"Validation 1 through Validation 10 - full criteria preserved."}
]

wb = Workbook()
ws = wb.active; ws.title = "TestPlan"
tc = ["Index","SS / Module","Feature","Test Case Name","Speed","Mode","Memory Start Offset","Memory End Offset","Test Description","Test Steps / Procedure","Impacted Registers","Validation / Acceptance Criteria","Remarks"]
ws.append(tc)
for r in TP: ws.append([r.get(c,"") for c in tc])

ws2 = wb.create_sheet("MetaData")
mc = ["Test Case Name","Meta Headers","Meta Macros","Meta Arrays","Meta Types","Meta Test Description","Meta Test Steps / Procedure","Meta Impacted Registers","Meta Validation / Acceptance Criteria"]
ws2.append(mc)
for r in MD: ws2.append([r.get(c,"") for c in mc])

hf=Font(bold=True,color="FFFFFF",size=11)
hfl=PatternFill(start_color="4472C4",end_color="4472C4",fill_type="solid")
ha=Alignment(horizontal="center",vertical="center",wrap_text=True)
ca=Alignment(vertical="top",wrap_text=True)
tb=Border(left=Side(style="thin"),right=Side(style="thin"),top=Side(style="thin"),bottom=Side(style="thin"))
for s in [ws,ws2]:
    for c in s[1]: c.font=hf;c.fill=hfl;c.alignment=ha;c.border=tb
    for row in s.iter_rows(min_row=2):
        for c in row: c.alignment=ca;c.border=tb
    s.freeze_panes="A2"
ws2.sheet_state="veryHidden"

buf=io.BytesIO()
wb.save(buf)
print(base64.b64encode(buf.getvalue()).decode("ascii"))
